	GetAll(ctx context.Context) ([]entity.Courier, error)
	Create(ctx context.Context, courier *entity.Courier) (int, error)
	Update(ctx context.Context, courier *entity.Courier) error
}

type CourierCreateRequest struct {
	Name   string `json:"name"`
	Phone  string `json:"phone"`
	Status string `json:"status"`
}

func (u *CourierUseCase) GetCourier(ctx context.Context, id int) (*model.Courier, error) {
	courierDB, err := u.repository.GetOneByID(ctx, id)

	if err != nil {
		if errors.Is(err, repository.ErrNotFound) {
			return nil, ErrNotFound
		}
		return nil, err
	}

func (r *CourierRepository) GetOneByID(ctx context.Context, id int) (*entity.Courier, error) {
	row := r.pool.QueryRow(ctx,
		"SELECT id, name, phone, status FROM couriers WHERE id = $1;", id,
	)

	var c entity.Courier
	err := row.Scan(&c.ID, &c.Name, &c.Phone, &c.Status)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, ErrNotFound
		}
		return nil, fmt.Errorf("database error: %w", err)
	}

func (c *CourierController) Get(w http.ResponseWriter, r *http.Request) {
	idStr := chi.URLParam(r, "id")
	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, `{"error":"invalid id"}`, http.StatusBadRequest)
		return
	}

	cr, err := c.useCase.GetCourier(r.Context(), id)
	if err != nil {
		switch err {
		case usecase.ErrNotFound:
			http.Error(w, `{"error":"not found"}`, http.StatusNotFound)
		case usecase.ErrBadRequest:
			http.Error(w, `{"error":"bad request"}`, http.StatusBadRequest)
		default:
			http.Error(w, `{"error":"database error"}`, http.StatusInternalServerError)
		}
		return
	}

	resp := dto.CourierResponse{
		ID:     cr.ID,
		Name:   cr.Name,
		Phone:  cr.Phone,
		Status: cr.Status,
	}
	writeJSON(w, http.StatusOK, resp)
}

func IsValidStatus(s string) bool {
	switch s {
	case StatusAvailable, StatusBusy, StatusPaused:
		return true
	}
	return false
}
